<?php
declare(strict_types=1);namespace App\Controllers;use App\Core\{Csrf,Request,Response,View};use App\Repositories\SecurityGroupRepository;use App\Security\Auth;use App\Services\SecurityGroupService;use Throwable;
final readonly class SecurityGroupController{public function __construct(private View $view,private SecurityGroupRepository $repo,private SecurityGroupService $service,private Csrf $csrf){}public function index(Request $r):void{$this->allow();$this->view->render('security/groups',['title'=>'Grupos de seguridad','groups'=>$this->repo->all(),'permissions'=>$this->repo->permissions(),'csrf'=>$this->csrf]);}public function save(Request $r):void{$this->allow();$this->run(fn()=>$this->service->save($r->input));}public function delete(Request $r):void{$this->allow();$this->run(fn()=>$this->service->delete($r->int('id')));}private function run(callable $fn):never{try{$fn();Response::redirect('/security/groups');}catch(Throwable $e){http_response_code(422);exit(htmlspecialchars($e->getMessage(),ENT_QUOTES,'UTF-8'));}}private function allow():void{if(!Auth::can('groups.manage')){http_response_code(403);exit('Sin permiso');}}}
